def lager(d, butikk, vare):
    if butikk not in d:
        return 0
    if vare not in d[butikk]:
        return 0
    return d[butikk][vare]

def totalt(d, vare):
    t = 0
    for butikk in d:
        t = t + lager(d, butikk, vare)
    return t

